package io.github.jaeseongs95.opermand.domain.attachment;

import java.util.Objects;
import java.util.regex.Pattern;

/**
 * The identifier of an encrypted operation-body attachment: 48 lowercase hex characters generated by the application. Kept as its own type so it never mixes with
 * {@code OperationId} or {@code ArtifactId}, and validated strictly so the file path {@code <attachments>/<id[0..2]>/<id>} can never carry path traversal.
 */
public record AttachmentId(String value) {

    private static final Pattern SHAPE = Pattern.compile("[a-f0-9]{48}");

    public AttachmentId {
        Objects.requireNonNull(value, "value");
        if (!SHAPE.matcher(value).matches()) {
            throw new IllegalArgumentException("An attachment id is 48 lowercase hex characters");
        }
    }

    /** The two-hex-character bucket directory prefix used under the attachments root. */
    public String bucket() {
        return value.substring(0, 2);
    }
}
